import re, urllib.request, urllib.parse, json, time, html as ihtml

names = ["jacaranda web", "brissie sites", "kooka web", "stormbird", "bilby web",
         "puggle web", "bunya web", "banksia web"]
hdr = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/120.0 Safari/537.36"}
out = {}
for n in names:
    url = "https://abr.business.gov.au/Search/ResultsActive?SearchText=" + urllib.parse.quote(n)
    try:
        req = urllib.request.Request(url, headers=hdr)
        page = urllib.request.urlopen(req, timeout=20).read().decode("utf-8", "replace")
        total = re.search(r'TotalResultsCount[^>]*value="(\d+)"', page)
        rows = re.findall(r'Results\.NameItems\[\d+\]\.Compressed[^>]*value="([^"]+)"', page)
        parsed = []
        for r in rows[:15]:
            parts = ihtml.unescape(r).split(",")
            if len(parts) > 7:
                nm = re.sub(r"\s+", " ", parts[5]).strip()
                parsed.append({"name": nm, "type": parts[8].strip() if len(parts) > 8 else parts[7].strip()})
        out[n] = {"total": int(total.group(1)) if total else -1, "top": parsed}
    except Exception as e:
        out[n] = {"error": str(e)}
    time.sleep(1.5)
print(json.dumps(out, indent=1))
EOF

