/* Brissie Sites — studio one-pager. Palette from brand/kit.md. */
:root {
  --ink: #17323C;
  --primary: #0E7C7B;
  --primary-dark: #0A5F5E;
  --accent: #F28C28;
  --accent-soft: #FDEBD3;
  --paper: #FBF7F0;
  --card: #FFFFFF;
  --muted: #5A7177;
  --line: #E4DCCF;
  --on-dark: #F4EFE6;
  --success: #2F8F5B;
  --radius: 14px;
  --maxw: 1080px;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: system-ui, "Segoe UI", "Avenir Next", "Helvetica Neue", Arial, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
  font-size: 17px;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { line-height: 1.15; letter-spacing: -0.02em; margin: 0 0 .5em; }
h1 { font-size: clamp(2.1rem, 6vw, 3.4rem); font-weight: 800; }
h2 { font-size: clamp(1.6rem, 4vw, 2.2rem); font-weight: 800; }
h3 { font-size: 1.15rem; font-weight: 700; }
p { margin: 0 0 1em; }

a { color: var(--primary); }
a:hover { color: var(--primary-dark); }

.wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 20px; }

/* ---------- header ---------- */
.site-header {
  position: sticky; top: 0; z-index: 10;
  background: rgba(251, 247, 240, .92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.site-header .wrap {
  display: flex; align-items: center; justify-content: space-between;
  padding-top: 10px; padding-bottom: 10px;
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); }
.brand svg { display: block; }
.brand .brand-name { font-weight: 800; font-size: 1.2rem; letter-spacing: -0.03em; }
.brand .brand-name .sites { color: var(--primary); font-weight: 700; }
.nav-email {
  font-size: .95rem; font-weight: 600;
  color: var(--primary); text-decoration: none;
  border: 1.5px solid var(--primary); border-radius: 999px;
  padding: 6px 14px;
}
.nav-email:hover { background: var(--primary); color: #fff; }

/* ---------- hero ---------- */
.hero {
  background:
    radial-gradient(900px 320px at 85% -10%, var(--accent-soft), transparent 60%),
    radial-gradient(700px 300px at -10% 20%, #DDF0EE, transparent 55%),
    var(--paper);
  padding: 64px 0 56px;
}
.hero .kicker {
  display: inline-block;
  background: var(--accent-soft);
  color: #8A5312;
  font-weight: 700; font-size: .85rem;
  border-radius: 999px; padding: 4px 12px;
  margin-bottom: 18px;
}
.hero p.lede { font-size: 1.25rem; color: var(--muted); max-width: 34em; }
.hero .cta-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 26px; }
.btn {
  display: inline-block; text-decoration: none; font-weight: 700;
  border-radius: 10px; padding: 13px 22px; font-size: 1.05rem;
}
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); color: #fff; }
.btn-ghost { border: 2px solid var(--ink); color: var(--ink); }
.btn-ghost:hover { background: var(--ink); color: var(--on-dark); }
.hero .micro { margin-top: 16px; font-size: .9rem; color: var(--muted); }

/* ---------- generic sections ---------- */
section { padding: 52px 0; }
section.alt { background: var(--card); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.section-head { max-width: 40em; margin-bottom: 30px; }
.section-head p { color: var(--muted); font-size: 1.1rem; }

/* how it works */
.steps { display: grid; gap: 16px; grid-template-columns: 1fr; padding: 0; margin: 0; list-style: none; }
.steps li {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 22px 22px 22px 70px; position: relative;
}
.steps .n {
  position: absolute; left: 20px; top: 22px;
  width: 34px; height: 34px; border-radius: 50%;
  background: var(--primary); color: #fff;
  font-weight: 800; display: grid; place-items: center;
}
.steps h3 { margin-bottom: .3em; }
.steps p { margin: 0; color: var(--muted); }

/* what you get */
.get-grid { display: grid; gap: 12px 28px; grid-template-columns: 1fr; margin: 0; padding: 0; list-style: none; }
.get-grid li { padding-left: 30px; position: relative; }
.get-grid li::before {
  content: ""; position: absolute; left: 0; top: 4px;
  width: 18px; height: 18px; border-radius: 50%;
  background: var(--success);
  -webkit-mask: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="%23000" d="M9 16.2 4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4z"/></svg>') center/contain no-repeat;
  mask: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="%23000" d="M9 16.2 4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4z"/></svg>') center/contain no-repeat;
}

/* pricing */
.price-grid { display: grid; gap: 18px; grid-template-columns: 1fr; }
.price-card {
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 28px;
}
.price-card.feature { border: 2px solid var(--primary); position: relative; }
.price-card .flag {
  position: absolute; top: -13px; left: 22px;
  background: var(--accent); color: #fff; font-size: .8rem; font-weight: 700;
  padding: 3px 12px; border-radius: 999px;
}
.price-card .amount { font-size: 2.6rem; font-weight: 800; letter-spacing: -0.03em; }
.price-card .amount small { font-size: 1rem; font-weight: 600; color: var(--muted); }
.price-card ul { margin: 14px 0 0; padding-left: 20px; color: var(--muted); }
.price-card li { margin-bottom: 6px; }
.price-note { margin-top: 18px; font-size: .92rem; color: var(--muted); }

/* portfolio */
.samples-grid { display: grid; gap: 16px; grid-template-columns: 1fr; }
.sample-card {
  display: block; text-decoration: none; color: var(--ink);
  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 20px; transition: transform .12s ease, box-shadow .12s ease;
}
.sample-card:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(23,50,60,.08); color: var(--ink); }
.sample-card .thumb {
  height: 110px; border-radius: 9px; margin-bottom: 14px;
  display: grid; place-items: center; color: rgba(255,255,255,.9);
  font-size: 2rem; font-weight: 800;
}
.sample-card h3 { margin-bottom: 2px; }
.sample-card .cat { color: var(--muted); font-size: .9rem; margin: 0; }
.sample-card .view { color: var(--primary); font-weight: 700; font-size: .92rem; }

/* FAQ */
.faq details { background: var(--card); border: 1px solid var(--line); border-radius: 10px; margin-bottom: 10px; }
.faq summary { cursor: pointer; padding: 15px 20px; font-weight: 700; list-style: none; }
.faq summary::-webkit-details-marker { display: none; }
.faq summary::after { content: "+"; float: right; color: var(--primary); font-weight: 800; }
.faq details[open] summary::after { content: "–"; }
.faq details p { padding: 0 20px 16px; margin: 0; color: var(--muted); }

/* contact */
.contact-band {
  background: var(--ink); color: var(--on-dark);
  border-radius: var(--radius); padding: 40px 28px; text-align: center;
}
.contact-band h2 { color: #fff; }
.contact-band p { color: #C9D6D2; max-width: 34em; margin-left: auto; margin-right: auto; }
.contact-band .btn { margin-top: 8px; }
.contact-band .email-fallback { margin-top: 14px; font-size: .95rem; color: #C9D6D2; }
.contact-band .email-fallback a { color: var(--accent); }

/* footer */
.site-footer { padding: 34px 0 44px; color: var(--muted); font-size: .9rem; }
.site-footer .wrap { display: flex; flex-direction: column; gap: 6px; }

/* ---------- >= 760px ---------- */
@media (min-width: 760px) {
  .hero { padding: 88px 0 76px; }
  section { padding: 68px 0; }
  .steps { grid-template-columns: repeat(3, 1fr); }
  .steps li { padding: 74px 24px 24px; }
  .get-grid { grid-template-columns: 1fr 1fr; }
  .price-grid { grid-template-columns: 1.2fr 1fr; align-items: start; }
  .samples-grid { grid-template-columns: repeat(3, 1fr); }
  .contact-band { padding: 56px; }
  .site-footer .wrap { flex-direction: row; justify-content: space-between; }
}

